"""Background escalation worker for the durable incident store."""

from __future__ import annotations

import time
from collections.abc import Callable

from .models import Incident
from .sqlite_store import SQLiteIncidentStore


class EscalationWorker:
    """Runs escalation claims and completions against a store."""

    def __init__(
        self,
        store: SQLiteIncidentStore,
        worker_id: str,
        clock: Callable[[], float] = time.time,
    ) -> None:
        self.store = store
        self.worker_id = worker_id
        self.clock = clock

    def run_once(self, now: float | None = None) -> Incident | None:
        ts = self.clock() if now is None else float(now)
        claimed = self.store.claim_due_escalation(self.worker_id, ts)
        if claimed is None:
            return None
        return self.store.complete_escalation(claimed.id, self.worker_id, ts)

    def run_until_idle(
        self, max_incidents: int | None = None, now: float | None = None
    ) -> list[Incident]:
        ts = self.clock() if now is None else float(now)
        completed: list[Incident] = []
        guard = 0
        while True:
            guard += 1
            if guard > 10000:
                break
            if max_incidents is not None and len(completed) >= max_incidents:
                break
            result = self.run_once(ts)
            if result is None:
                break
            completed.append(result)
        return completed

"""Standard-library HTTP server for the durable incident operations application."""

from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse

from .escalation import EscalationWorker
from .models import (
    Incident,
    IncidentError,
    IncidentNotFound,
    IncidentStatus,
    InvalidTransition,
    Severity,
    VersionConflict,
)
from .sqlite_store import SQLiteIncidentStore

STATIC_DIR = Path(__file__).with_name("static")


def incident_to_dict(incident: Incident) -> dict:
    return {
        "id": incident.id,
        "fingerprint": incident.fingerprint,
        "title": incident.title,
        "severity": incident.severity.value,
        "status": incident.status.value,
        "owner": incident.owner,
        "alert_count": incident.alert_count,
        "version": incident.version,
        "escalation_level": incident.escalation_level,
        "created_at": incident.created_at,
        "updated_at": incident.updated_at,
        "sla_deadline": incident.sla_deadline,
    }


def event_to_dict(event) -> dict:
    return {
        "id": event.id,
        "incident_id": event.incident_id,
        "type": event.type,
        "timestamp": event.timestamp,
        "details": event.details,
    }


def create_server(
    store: SQLiteIncidentStore,
    host: str = "127.0.0.1",
    port: int = 8080,
) -> ThreadingHTTPServer:
    """Construct and bind a server without starting its request loop."""

    class Handler(BaseHTTPRequestHandler):
        def do_GET(self) -> None:
            parsed = urlparse(self.path)
            path = parsed.path.rstrip("/") or "/"
            if path == "/api/incidents":
                params = self._query(parsed.query)
                incidents = store.list(
                    status=params.get("status"),
                    severity=params.get("severity"),
                    owner=params.get("owner"),
                )
                self._json(200, [incident_to_dict(i) for i in incidents])
                return
            if path == "/api/summary":
                self._json(200, store.summary())
                return
            if path.startswith("/api/incidents/"):
                incident_id = path[len("/api/incidents/") :]
                incident = store.get(incident_id)
                if incident is None:
                    self._json(404, {"error": "incident not found", "id": incident_id})
                    return
                payload = incident_to_dict(incident)
                payload["events"] = [event_to_dict(e) for e in store.events(incident_id)]
                self._json(200, payload)
                return
            if path in {"", "/", "/index.html"}:
                self._file("index.html", "text/html; charset=utf-8")
                return
            if path == "/app.js":
                self._file("app.js", "text/javascript; charset=utf-8")
                return
            if path == "/styles.css":
                self._file("styles.css", "text/css; charset=utf-8")
                return
            self._json(404, {"error": "not found", "path": path})

        def do_POST(self) -> None:
            parsed = urlparse(self.path)
            path = parsed.path.rstrip("/") or "/"
            if path == "/api/alerts":
                self._handle_alerts()
                return
            if path == "/api/escalations/run":
                self._handle_escalation_run(parsed.query)
                return
            if path == "/api/incidents":
                self._handle_alerts()
                return
            self._json(404, {"error": "not found", "path": path})

        def do_PATCH(self) -> None:
            parsed = urlparse(self.path)
            path = parsed.path.rstrip("/") or "/"
            if not path.startswith("/api/incidents/"):
                self._json(404, {"error": "not found", "path": path})
                return
            incident_id = path[len("/api/incidents/") :]
            try:
                payload = self._body()
            except json.JSONDecodeError as exc:
                self._json(400, {"error": "invalid JSON", "detail": str(exc)})
                return
            if not isinstance(payload, dict):
                self._json(400, {"error": "JSON body must be an object"})
                return
            if "expected_version" not in payload:
                self._json(
                    400, {"error": "expected_version is required"}
                )
                return
            try:
                expected_version = int(payload["expected_version"])
            except (TypeError, ValueError):
                self._json(400, {"error": "expected_version must be an integer"})
                return
            status_value = payload.get("status")
            if status_value is not None and status_value not in {
                s.value for s in IncidentStatus
            }:
                self._json(
                    400, {"error": "invalid status", "value": status_value}
                )
                return
            try:
                updated = store.update(
                    incident_id,
                    expected_version,
                    owner=payload.get("owner"),
                    status=status_value,
                    idempotency_key=payload.get("idempotency_key"),
                )
            except IncidentNotFound:
                self._json(404, {"error": "incident not found", "id": incident_id})
                return
            except VersionConflict as exc:
                self._json(409, {"error": "version conflict", "detail": str(exc)})
                return
            except InvalidTransition as exc:
                self._json(409, {"error": "invalid transition", "detail": str(exc)})
                return
            except IncidentError as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(200, incident_to_dict(updated))

        def _handle_alerts(self) -> None:
            try:
                payload = self._body()
            except json.JSONDecodeError as exc:
                self._json(400, {"error": "invalid JSON", "detail": str(exc)})
                return
            if not isinstance(payload, dict):
                self._json(400, {"error": "JSON body must be an object"})
                return
            if "severity" in payload and payload["severity"] not in {
                s.value for s in Severity
            }:
                self._json(400, {"error": "invalid severity", "value": payload.get("severity")})
                return
            try:
                incident, created = store.ingest_alert(
                    fingerprint=payload.get("fingerprint") or payload.get("title", ""),
                    title=payload.get("title", ""),
                    severity=payload.get("severity", Severity.P3.value),
                    source=payload.get("source", "unknown"),
                    details=payload.get("details"),
                    idempotency_key=payload.get("idempotency_key"),
                )
            except ValueError as exc:
                self._json(400, {"error": str(exc)})
                return
            except IncidentError as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(201 if created else 200, incident_to_dict(incident))

        def _handle_escalation_run(self, query: str) -> None:
            params = self._query(query)
            worker_id = params.get("worker_id", "http-worker")
            max_incidents = params.get("max_incidents")
            max_value = None
            if max_incidents is not None:
                try:
                    max_value = int(max_incidents)
                except ValueError:
                    self._json(400, {"error": "max_incidents must be an integer"})
                    return
            store.recover_expired_claims()
            worker = EscalationWorker(store, worker_id)
            completed = worker.run_until_idle(max_incidents=max_value)
            self._json(
                200,
                {"worker_id": worker_id, "completed": [incident_to_dict(i) for i in completed]},
            )

        @staticmethod
        def _query(query: str) -> dict[str, str]:
            params: dict[str, str] = {}
            for chunk in query.split("&"):
                if not chunk:
                    continue
                key, sep, value = chunk.partition("=")
                params[key] = value.replace("+", " ")
            return params

        def _body(self) -> dict:
            length = int(self.headers.get("Content-Length", "0"))
            raw = self.rfile.read(length) if length else b"{}"
            return json.loads(raw)

        def _file(self, name: str, content_type: str) -> None:
            try:
                body = (STATIC_DIR / name).read_bytes()
            except FileNotFoundError:
                self.send_error(404)
                return
            self.send_response(200)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _json(self, status: int, value: object) -> None:
            body = json.dumps(value, default=str).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *args: object) -> None:
            return

    return ThreadingHTTPServer((host, port), Handler)

:root {
  --bg: #eef2f7;
  --panel: #ffffff;
  --border: #d8e0ea;
  --ink: #172033;
  --muted: #5b6678;
  --accent: #3154a5;
  --accent-dim: #e3eaf7;
  --p1: #c0392b;
  --p2: #d97706;
  --p3: #2563eb;
  --p4: #4b5563;
  --ok: #15803d;
  --warn: #b45309;
  --err: #b91c1c;
  color: var(--ink);
  background: var(--bg);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
}

* { box-sizing: border-box; }
body { margin: 0; }

main {
  width: 100%;
  max-width: 920px;
  margin: 0 auto;
  padding: 16px;
  min-height: 100vh;
}

.app-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px;
  margin-bottom: 12px;
}

.eyebrow { color: var(--accent); font-weight: 700; text-transform: uppercase; letter-spacing: .08em; margin: 0 0 4px; font-size: 11px; }
h1 { margin: 0; font-size: 20px; }
h2 { margin: 0 0 8px; font-size: 15px; }

.summary { text-align: right; }
.summary-total { margin: 0; font-size: 12px; color: var(--muted); }
.summary-total span { font-size: 22px; font-weight: 800; color: var(--ink); }
.summary-breakdown { display: flex; flex-wrap: wrap; gap: 6px; justify-content: flex-end; margin-top: 6px; }
.summary-chip { font-size: 11px; background: var(--accent-dim); color: var(--accent); border-radius: 999px; padding: 2px 8px; white-space: nowrap; }

.controls {
  display: flex;
  gap: 8px;
  align-items: end;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 12px;
  margin-bottom: 12px;
}
.controls label { display: flex; flex-direction: column; gap: 4px; font-size: 11px; color: var(--muted); flex: 1; }
input, select, button {
  box-sizing: border-box;
  min-height: 38px;
  padding: 6px 8px;
  font: inherit;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: white;
  color: var(--ink);
  width: 100%;
}
button {
  border: 0;
  color: white;
  background: var(--accent);
  font-weight: 700;
  cursor: pointer;
  padding: 0 16px;
}
button.secondary { background: var(--muted); }
button:disabled { opacity: .5; cursor: not-allowed; }

.board { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.incident-list-wrap, .incident-detail, .timeline {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 12px;
}

.incident-list { list-style: none; margin: 0; padding: 0; max-height: 480px; overflow-y: auto; }
.incident-row {
  display: grid;
  grid-template-columns: 40px 1fr auto;
  gap: 8px;
  align-items: center;
  padding: 8px;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
}
.incident-row:hover { background: var(--accent-dim); }
.incident-row.selected { border-color: var(--accent); background: var(--accent-dim); }
.sev-badge {
  width: 40px; height: 40px;
  display: grid; place-items: center;
  border-radius: 8px; color: white; font-weight: 800; font-size: 13px;
}
.sev-P1 { background: var(--p1); }
.sev-P2 { background: var(--p2); }
.sev-P3 { background: var(--p3); }
.sev-P4 { background: var(--p4); }
.row-main { min-width: 0; }
.row-title { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row-meta { font-size: 11px; color: var(--muted); }
.row-status { font-size: 11px; font-weight: 700; text-transform: uppercase; }
.row-status.open { color: var(--p1); }
.row-status.acknowledged { color: var(--warn); }
.row-status.resolved { color: var(--ok); }

.incident-detail h3 { margin: 0 0 8px; font-size: 15px; }
.detail-grid { display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; font-size: 12px; margin-bottom: 12px; }
.detail-grid dt { color: var(--muted); }
.detail-grid dd { margin: 0; word-break: break-word; }
.detail-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.detail-actions input { flex: 1 1 140px; }
.owner-input { flex: 1 1 140px; }

.timeline { grid-column: 1 / -1; }
.timeline-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.timeline-item {
  border-left: 3px solid var(--accent);
  padding: 6px 10px;
  background: var(--accent-dim);
  border-radius: 0 8px 8px 0;
  font-size: 12px;
}
.timeline-item .event-type { font-weight: 700; }
.timeline-item .event-meta { color: var(--muted); }

.feedback { min-height: 20px; font-size: 12px; padding: 6px 10px; border-radius: 8px; margin: 0 0 8px; }
.feedback.ok { background: #dcfce7; color: var(--ok); }
.feedback.error { background: #fee2e2; color: var(--err); }

.empty-state { color: var(--muted); font-size: 12px; padding: 8px; }

@media (max-width: 640px) {
  .board { grid-template-columns: 1fr; }
  .app-header { flex-direction: column; }
  .summary { text-align: left; }
  .summary-breakdown { justify-content: flex-start; }
}

(function () {
  "use strict";

  const state = {
    filters: { status: "", severity: "" },
    selectedId: null,
    incidents: [],
    detail: null,
    feedback: { message: "", kind: "" },
  };

  const els = {
    app: document.getElementById("incident-app"),
    summary: document.getElementById("summary"),
    summaryTotal: document.getElementById("summary-total"),
    summaryBreakdown: document.getElementById("summary-breakdown"),
    statusFilter: document.getElementById("status-filter"),
    severityFilter: document.getElementById("severity-filter"),
    refreshBtn: document.getElementById("refresh-btn"),
    feedback: document.getElementById("feedback"),
    incidentList: document.getElementById("incident-list"),
    emptyState: document.getElementById("empty-state"),
    incidentDetail: document.getElementById("incident-detail"),
    timeline: document.getElementById("timeline"),
    timelineList: document.getElementById("timeline-list"),
  };

  function setFeedback(message, kind) {
    state.feedback = { message: message || "", kind: kind || "" };
    els.feedback.textContent = state.feedback.message;
    els.feedback.className = "feedback" + (kind ? " " + kind : "");
  }

  async function fetchJson(url, options) {
    const response = await fetch(url, options);
    let payload = null;
    const text = await response.text();
    if (text) {
      try { payload = JSON.parse(text); } catch (e) { payload = { error: text }; }
    }
    return { ok: response.ok, status: response.status, payload };
  }

  function buildQuery(params) {
    const parts = [];
    for (const [key, value] of Object.entries(params)) {
      if (value !== "" && value !== null && value !== undefined) {
        parts.push(encodeURIComponent(key) + "=" + encodeURIComponent(value));
      }
    }
    return parts.length ? "?" + parts.join("&") : "";
  }

  async function refresh() {
    try {
      const query = buildQuery({
        status: state.filters.status,
        severity: state.filters.severity,
      });
      const res = await fetchJson("/api/incidents" + query);
      if (!res.ok) {
        setFeedback("Could not load incidents: " + (res.payload && res.payload.error), "error");
        return;
      }
      state.incidents = Array.isArray(res.payload) ? res.payload : [];
      renderList();
      await refreshSummary();
      if (state.selectedId) {
        await selectIncident(state.selectedId);
      } else {
        clearDetail();
      }
    } catch (err) {
      setFeedback("Network error: " + err.message, "error");
    }
  }

  async function refreshSummary() {
    try {
      const res = await fetchJson("/api/summary");
      if (res.ok && res.payload) {
        els.summaryTotal.textContent = String(res.payload.total || 0);
        const breakdown = els.summaryBreakdown;
        breakdown.replaceChildren();
        const byStatus = res.payload.by_status || {};
        const bySeverity = res.payload.by_severity || {};
        const renderChip = (label, count) => {
          const span = document.createElement("span");
          span.className = "summary-chip";
          span.textContent = label + ": " + count;
          breakdown.appendChild(span);
        };
        Object.keys(byStatus).sort().forEach((k) => renderChip(k, byStatus[k]));
        Object.keys(bySeverity).sort().forEach((k) => renderChip(k, bySeverity[k]));
      }
    } catch (err) {
      /* summary is best effort */
    }
  }

  function renderList() {
    els.incidentList.replaceChildren(...state.incidents.map(renderRow));
    els.emptyState.style.display = state.incidents.length ? "none" : "block";
  }

  function renderRow(incident) {
    const li = document.createElement("li");
    li.className = "incident-row" + (incident.id === state.selectedId ? " selected" : "");
    li.setAttribute("data-testid", "incident-row");
    li.dataset.id = incident.id;

    const badge = document.createElement("span");
    badge.className = "sev-badge sev-" + incident.severity;
    badge.textContent = incident.severity;

    const main = document.createElement("div");
    main.className = "row-main";
    const title = document.createElement("div");
    title.className = "row-title";
    title.textContent = incident.title;
    const meta = document.createElement("div");
    meta.className = "row-meta";
    meta.textContent =
      "v" + incident.version + " · alerts " + incident.alert_count +
      (incident.owner ? " · " + incident.owner : "");
    main.appendChild(title);
    main.appendChild(meta);

    const status = document.createElement("span");
    status.className = "row-status " + incident.status;
    status.textContent = incident.status;

    li.appendChild(badge);
    li.appendChild(main);
    li.appendChild(status);
    li.addEventListener("click", () => selectIncident(incident.id));
    return li;
  }

  function clearDetail() {
    state.detail = null;
    els.incidentDetail.replaceChildren(
      (() => {
        const p = document.createElement("p");
        p.className = "empty-state";
        p.textContent = "Select an incident to view details.";
        return p;
      })()
    );
    els.timelineList.replaceChildren();
  }

  async function selectIncident(id) {
    state.selectedId = id;
    try {
      const res = await fetchJson("/api/incidents/" + encodeURIComponent(id));
      if (!res.ok || !res.payload) {
        setFeedback("Could not load incident: " + (res.payload && res.payload.error), "error");
        clearDetail();
        renderList();
        return;
      }
      state.detail = res.payload;
      renderDetail(res.payload);
      renderTimeline(res.payload.events || []);
      renderList();
    } catch (err) {
      setFeedback("Network error: " + err.message, "error");
    }
  }

  function renderDetail(incident) {
    const wrap = els.incidentDetail;
    wrap.replaceChildren();

    const title = document.createElement("h3");
    title.textContent = incident.title;
    wrap.appendChild(title);

    const grid = document.createElement("dl");
    grid.className = "detail-grid";
    const rows = [
      ["ID", incident.id],
      ["Severity", incident.severity],
      ["Status", incident.status],
      ["Owner", incident.owner || "—"],
      ["Version", incident.version],
      ["Alerts", incident.alert_count],
      ["Escalation", incident.escalation_level],
      ["Fingerprint", incident.fingerprint],
      ["SLA deadline", new Date(incident.sla_deadline * 1000).toLocaleString()],
      ["Updated", new Date(incident.updated_at * 1000).toLocaleString()],
    ];
    for (const [label, value] of rows) {
      const dt = document.createElement("dt");
      dt.textContent = label;
      const dd = document.createElement("dd");
      dd.textContent = String(value);
      grid.appendChild(dt);
      grid.appendChild(dd);
    }
    wrap.appendChild(grid);

    const actions = document.createElement("div");
    actions.className = "detail-actions";

    const ownerInput = document.createElement("input");
    ownerInput.setAttribute("data-testid", "owner-input");
    ownerInput.className = "owner-input";
    ownerInput.type = "text";
    ownerInput.value = incident.owner || "";
    ownerInput.placeholder = "Owner";
    ownerInput.id = "owner-input";
    actions.appendChild(ownerInput);

    const ack = document.createElement("button");
    ack.setAttribute("data-testid", "acknowledge-action");
    ack.textContent = "Acknowledge";
    ack.addEventListener("click", () => updateIncident({
      owner: ownerInput.value,
      status: "acknowledged",
    }));
    actions.appendChild(ack);

    const resolve = document.createElement("button");
    resolve.setAttribute("data-testid", "resolve-action");
    resolve.textContent = "Resolve";
    resolve.className = "secondary";
    resolve.addEventListener("click", () => updateIncident({
      owner: ownerInput.value,
      status: "resolved",
    }));
    actions.appendChild(resolve);

    wrap.appendChild(actions);
  }

  function renderTimeline(events) {
    els.timelineList.replaceChildren(...events.map(renderEvent));
  }

  function renderEvent(event) {
    const li = document.createElement("li");
    li.className = "timeline-item";
    const type = document.createElement("div");
    type.className = "event-type";
    type.textContent = event.type;
    const meta = document.createElement("div");
    meta.className = "event-meta";
    const when = new Date(event.timestamp * 1000).toLocaleString();
    const details = event.details ? JSON.stringify(event.details) : "";
    meta.textContent = when + (details ? " · " + details : "");
    li.appendChild(type);
    li.appendChild(meta);
    return li;
  }

  async function updateIncident(changes) {
    if (!state.detail) return;
    const payload = {
      expected_version: state.detail.version,
      ...changes,
    };
    const res = await fetchJson(
      "/api/incidents/" + encodeURIComponent(state.detail.id),
      {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      }
    );
    if (res.ok && res.payload) {
      setFeedback("Incident updated", "ok");
      await selectIncident(state.detail.id);
      await refresh();
    } else {
      const message = (res.payload && res.payload.error) || ("HTTP " + res.status);
      setFeedback("Update failed: " + message, "error");
      if (res.status === 409 && state.detail) {
        await selectIncident(state.detail.id);
      }
    }
  }

  els.statusFilter.addEventListener("change", () => {
    state.filters.status = els.statusFilter.value;
    refresh();
  });
  els.severityFilter.addEventListener("change", () => {
    state.filters.severity = els.severityFilter.value;
    refresh();
  });
  els.refreshBtn.addEventListener("click", refresh);

  window.incidentOps = {
    refresh,
    selectIncident,
    getState: () => ({
      filters: { ...state.filters },
      selectedIncidentId: state.selectedId,
      incidents: state.incidents,
      feedback: state.feedback.message,
    }),
  };

  refresh();
})();

